      cabezal(b, 150, 150, 40, 110); coraza(b, 190, 150, 300, 110); cabezal(b, 490, 150, 40, 110); tubos(b, 190, 150, 300, 110, 5, false);
      flujo(b, 100, 205, 148, 205, NA, 'vapor', 96, 200, 'end');
      flujo(b, 440, 92, 440, 148, AZ, 'agua', 440, 84); flujo(b, 230, 262, 230, 320, AZ);
      flujo(b, 510, 262, 510, 320, K.aguaO, 'condensado', 510, 338);
