      s('rect', { x: 303, y: 326, width: 114, height: 16, fill: K.agua, opacity: 0.9 }, c);
      flujo(c, 360, 50 - 8, 360, 58, NA, 'vapor', 360, 50 - 14);
      flujo(c, 250, 280, 298, 280, AZ, 'agua', 246, 285, 'end'); flujo(c, 298, 118, 250, 118, AZ);
      flujo(c, 360, 346, 360, 380, K.aguaO, 'condensado', 372, 376, 'start');
      venteo(c, 432, 318, 'start', 12);
      txt(c, 620, 200, '(c) vertical, con el vapor', { ancla: 'middle', tam: 15, peso: 700, color: TXT });
      txt(c, 620, 220, 'bajando por los tubos,', { ancla: 'middle', tam: 15, peso: 700, color: TXT });
      txt(c, 620, 240, 'como E-201', { ancla: 'middle', tam: 15, peso: 700, color: TXT });
      // (d) vertical, vapor en la coraza
      var d = grupo(svg); S.g.push(d);
      cabezal(d, 300, 60, 120, 34); coraza(d, 300, 94, 120, 210); cabezal(d, 300, 304, 120, 34); tubos(d, 300, 94, 120, 210, 5, true);
      s('rect', { x: 303, y: 282, width: 114, height: 20, fill: K.agua, opacity: 0.9 }, d);
      flujo(d, 470, 112, 422, 112, NA, 'vapor', 476, 117, 'start');
      flujo(d, 360, 384, 360, 340, AZ, 'agua', 380, 380, 'start'); flujo(d, 360, 58, 360, 18 + 20, AZ);
      flujo(d, 422, 296, 470, 296, K.aguaO, 'condensado', 476, 301, 'start');
