        D.t(g, cx, Y0 - 30, 'G = ' + c.G + ' s⁻¹', { tam: 13, peso: 600, ancla: 'middle' });
        o.dat = grupo(g); lineas(o.dat, x + 2, Y0 + L + 22, [n(c.P, 1) + ' W; ' + n(c.rpm, 0) + ' r/min', 'punta: ' + n(c.punta, 2) + ' m/s', 'λ_K = ' + n(c.lk, 0) + ' µm; 2λ_K = ' + n(2 * c.lk, 0) + ' µm'], { tam: 12 });
