      S.vol = grupo(svg); D.t(S.vol, 330, 16, '3 cámaras de ' + n(FC.vc, 2) + ' m³, de ' + n(FC.lado, 2) + ' m de lado; hidrofoil de ' + n(FC.d, 2) + ' m', { tam: 12, ancla: 'middle', color: K.tinta2 });
