      lineas(S.comp, 30, YB + 64, ['con 70, 50 y 30 s⁻¹ quedaría 1 de cada ' + n(1 / FC.n705030[3], 1) + '; con 40 en las tres, 1 de cada ' + n(1 / FC.n40[3], 1)], { tam: 12, color: OL });
      S.poner = function (k, f) { var v = 1 + (FC.n[k + 1] - 1) * f; S.bar[k].b.setAttribute('width', (BW * v).toFixed(1)); D.ponerTexto(S.bar[k].t, 'n_' + (k + 1) + ' = ' + n(v, 3)); };
