      s('rect', { x: X0, y: Y0, width: X1 - X0, height: Y1 - Y0, fill: AGUA }, svg);
      s('path', { d: 'M' + X0 + ' ' + (Y0 - 14) + 'V' + Y1 + 'H' + X1 + 'V' + (Y0 - 14), fill: 'none', stroke: K.tinta, 'stroke-width': 2 }, svg);
      s('rect', { x: X0, y: Y1 - 5, width: X1 - X0, height: 5, fill: LODO_M }, svg);
      D.flecha(svg, 20, Y0 + 12, X0 + 26, Y0 + 12, { color: AGUA_O, ancho: 2.2, punta: 8 });
      D.t(svg, 14, Y0 - 8, 'entra', { tam: 12, color: K.tinta2 });
      D.flecha(svg, X1 - 30, Y0 + 6, X1 + 40, Y0 + 6, { color: AGUA_O, ancho: 2.2, punta: 8 });
