      D.t(svg, (X0 + X1) / 2, Y1 + 18, 'L = ' + n(HZ.Lt, 2) + ' m; 1,3 m de ancho; A = ' + n(HZ.A, 2) + ' m²', { tam: 12, ancla: 'middle', color: K.tinta2 });
      // las trayectorias: la partícula entra arriba, a la izquierda, y baja a v_s mientras el agua la lleva a v_h
      function tray(v, color) { var xf = Math.min(HZ.Lt, HZ.H / v * HZ.vh), zf = v / HZ.vh * xf; return { tr: D.trazo(svg, 'M' + X(0) + ' ' + Y(0) + 'L' + X(xf).toFixed(1) + ' ' + Y(zf).toFixed(1), { color: color, ancho: 2 }), xf: xf, zf: zf, v: v }; }
      S.tc = tray(HZ.vo, AZ); S.t2 = tray(HZ.v2, OL); S.t1 = tray(HZ.v1, S3);
      S.pc = D.punto(svg, X(0), Y(0), { r: 5 }); S.p2 = D.punto(svg, X(0), Y(0), { r: 5, color: LODO_O }); S.p1 = D.punto(svg, X(0), Y(0), { r: 4, color: LODO_M });
      S.mover = function (P, tr, f) { var x = tr.xf * f, z = tr.v / HZ.vh * x; P.setAttribute('cx', X(x).toFixed(1)); P.setAttribute('cy', Y(z).toFixed(1)); };
