      D.t(S.zona, X0 - 6, Y((1 - fr) * HZ.H) + 30, n(100 * fr, 0) + ' %', { tam: 12, peso: 600, ancla: 'end', color: S3 });
      D.t(S.zona, X0 - 6, Y((1 - fr) * HZ.H) + 46, 'se', { tam: 12, peso: 600, ancla: 'end', color: S3 });
      D.t(S.zona, X0 - 6, Y((1 - fr) * HZ.H) + 62, 'queda', { tam: 12, peso: 600, ancla: 'end', color: S3 });
