      for (var i = 0; i < 26; i++) gl.push([rnd(), rnd()]);
      S.gl = gl.map(function (p) { return { p: p, c: s('circle', { cx: (X0 + 8 + p[0] * (X1 - X0 - 16)).toFixed(1), cy: 0, r: 2.2, fill: ACEITE_M, stroke: ACEITE_O, 'stroke-width': 0.8 }, svg) }; });
      S.subir = function (f) { S.gl.forEach(function (g) { var y0 = Y1 - 6 - g.p[1] * (Y1 - Y0 - 12), y = Math.max(Y0 + 4, y0 - f * (Y1 - Y0)); g.c.setAttribute('cy', y.toFixed(1)); }); S.crema.setAttribute('height', (8 * f).toFixed(1)); };
      S.rac = grupo(svg);
